(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.27)*18 + Math.sin(x*0.015+t*0.32)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.15)*8 + Math.cos(sy*0.02+t*0.18)*6;
  const w2y = Math.cos(sy*0.025+t*0.2)*8 + Math.sin(sx*0.022-t*0.17)*6;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,-1],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,-1],
    [80+Math.sin(t*0.45)*60,40+Math.cos(t*0.65+1)*40,0.14,2.1,-1],
    [400+Math.cos(t*0.55+3)*70,200+Math.sin(t*0.75+2)*50,0.05,1.4,1],
    [200+Math.sin(t*0.7+1)*90,220+Math.cos(t*0.5+3)*60,0.11,2.4,-1],
    [300+Math.cos(t*0.38)*110,30+Math.sin(t*0.58+2)*45,0.085,1.8,1]
  ];
  let aS=0,iS=0,aC=0,iC=0;
  for(const[sX,sY,f,sp,tp]of src){
    const d=Math.sqrt((px-sX)**2+(py-sY)**2);
    const w=Math.sin(d*f-t*sp), amp=1.0/(1.0+d*0.003);
    if(tp>0){aS+=w*amp;aC++}else{iS+=w*amp;iC++}
  }
  const act=aS/Math.max(aC,1), inh=iS/Math.max(iC,1);
  const bg=(Math.sin(px*0.04+py*0.025+t*0.8)+Math.sin(px*0.03-py*0.04+t*1.1)+Math.sin(px*0.05+t*0.6)*Math.cos(py*0.045-t*0.7)+Math.sin((px+py)*0.12+t*2.5)*0.2+Math.sin((px-py)*0.1-t*2)*0.2)/2.8;
  const dist=Math.sqrt((px-cx)**2+(py-cy)**2), ang=Math.atan2(py-cy,px-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2-t*0.8)*0.5)*0.35;
  const cellX=px*0.12, cellY=py*0.12;
  const ci=Math.floor(cellX), cj=Math.floor(cellY);
  let minD=99, minD2=99;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const nx=ci+di+Math.sin(ci+di*3.7+t*0.4)*0.4+Math.cos(cj+dj*2.3+t*0.3)*0.4;
    const ny=cj+dj+Math.cos(ci+di*2.1+t*0.35)*0.4+Math.sin(cj+dj*4.1+t*0.45)*0.4;
    const d=Math.sqrt((cellX-nx)**2+(cellY-ny)**2);
    if(d<minD){minD2=minD;minD=d}else if(d<minD2)minD2=d;
  }
  const voronoi=(minD2-minD)*2.0;
  const feed=act-inh*0.65+bg*0.35+spiral;
  const reaction=Math.tanh(feed*2.0+voronoi*0.8);
  const cell=Math.tanh((Math.sin(px*0.15)*Math.sin(py*0.15)+Math.sin((px+py)*0.1+t)*0.5)*1.5)*0.3;
  const moire=Math.sin(px*0.08+t*0.5)*Math.sin(py*0.08-t*0.4)*0.15;
  const edgeGlow=Math.max(0,Math.abs(reaction)-0.6)*2.5;
  const blend=reaction*0.6+cell*0.2+voronoi*0.1+moire;
  const v=blend*0.5+0.5;
