  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+edgeGlow*0.3;
  const shift=Math.sin(dist*0.01+t*0.5)*0.02;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum+shift*255))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum-shift*200))|0
  ];
}
